<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import * as maplibregl from 'maplibre-gl'
import type { GeoJSONSource } from 'maplibre-gl'
import mapWorkerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url'
import 'maplibre-gl/dist/maplibre-gl.css'
import { MapPin, CalendarDays, Satellite, X } from '@lucide/vue'
import type { Analysis, Point } from '../huanuco'
import { percent } from '../huanuco'
import type { FeatureCollection, Geometry } from 'geojson'
const props=defineProps<{analysis: Analysis | null; confidence:string; fireType:string; year:number; grid:number; mode:'sensor'|'harmonized'}>()
maplibregl.setWorkerUrl(mapWorkerUrl)
const selectedDate=ref(props.year === 2026 ? '2026-11-13' : props.year+'-09-30'), period=ref('week'), mapElement=ref<HTMLDivElement>()
const data=ref<Point[]>([]), selected=ref<Point | null>(null), error=ref(''), busy=ref(false), truncated=ref(false)
type CellProps = { x:number; y:number; combined:number|null; disagreement:number|null; sensors:Record<string,{days:number|null;percentile:number|null;sample:number;ties:number|null}> }
const cells=ref<FeatureCollection<Geometry,CellProps>>({type:'FeatureCollection',features:[]}), selectedCell=ref<CellProps|null>(null)
let map: maplibregl.Map | undefined, requestId=0
const weekStart=computed(()=>{const day=new Date(selectedDate.value+'T00:00:00Z');day.setUTCDate(day.getUTCDate()-(day.getUTCDay()+6)%7);return day.toISOString().slice(0,10)})
const weekEnd=computed(()=>{const day=new Date(weekStart.value+'T00:00:00Z');day.setUTCDate(day.getUTCDate()+6);return day.toISOString().slice(0,10)})
watch(() => props.year, y => { selectedDate.value = y === 2026 ? '2026-11-13' : y + '-09-30' }, {flush:'sync'})
const range=computed(() => { const end=selectedDate.value; const start=new Date(end+'T00:00:00Z'); if(period.value==='week')start.setUTCDate(start.getUTCDate()-6); if(period.value==='month')start.setUTCDate(1); return {start: start.toISOString().slice(0,10)< props.year+'-01-01'?props.year+'-01-01':start.toISOString().slice(0,10),end} })
function draw(){if(!map?.getSource('detections'))return; (map.getSource('detections') as GeoJSONSource).setData({type:'FeatureCollection',features:data.value.map(d=>({type:'Feature',geometry:{type:'Point',coordinates:[d.longitude,d.latitude]},properties:{id:d.id,sensor:d.sensor}}))}); (map.getSource('cells') as GeoJSONSource).setData(cells.value);map.setLayoutProperty('points','visibility',props.mode==='sensor'?'visible':'none');map.setLayoutProperty('cell-fill','visibility',props.mode==='harmonized'?'visible':'none');map.setLayoutProperty('cell-line','visibility',props.mode==='harmonized'?'visible':'none')}
watch([range,()=>props.confidence,()=>props.fireType,()=>props.mode,()=>props.grid],async()=>{const id=++requestId;busy.value=true;error.value='';selected.value=null;selectedCell.value=null;data.value=[];cells.value={type:'FeatureCollection',features:[]};draw()
try{const common={confidence:props.confidence,fire_type:props.fireType};if(props.mode==='harmonized'){
 if(!weekStart.value.startsWith(String(props.year)) || !weekEnd.value.startsWith(String(props.year))) { if(id===requestId) error.value='La semana cruza el año seleccionado y no es comparable.';return }
 const q=new URLSearchParams({start:weekStart.value,grid:String(props.grid),...common});const r=await fetch('/api/huanuco/cells?'+q);if(!r.ok)throw new Error('No se pudo calcular la armonización por celda.');const result=await r.json();if(id!==requestId)return;cells.value=result
}else{const q=new URLSearchParams({...range.value,...common});const r=await fetch('/api/huanuco/points?'+q);if(!r.ok)throw new Error('No se pudieron cargar las observaciones.');const result=await r.json();if(id!==requestId)return;data.value=result.data;truncated.value=result.truncated}draw()
}catch(e){if(id!==requestId)return;error.value=e instanceof Error?e.message:'Error de conexión'}finally{if(id===requestId)busy.value=false}}, {immediate:true})
onMounted(async()=>{try{const response=await fetch('/geo/peru-departments.geojson');if(!response.ok)throw new Error('No se pudo cargar el límite de Huánuco.');const json=await response.json();const region=json.features.find((f:{properties:{shapeISO:string}})=>f.properties.shapeISO==='PE-HUC');if(!region||!mapElement.value)throw new Error('No se encontró el límite de Huánuco.');map=new maplibregl.Map({container:mapElement.value,center:[-76.2,-9.5],zoom:6,style:{version:8,sources:{imagery:{type:'raster',tiles:['https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,attribution:'Imagery © Esri, Maxar, Earthstar Geographics'},region:{type:'geojson',data:region},detections:{type:'geojson',data:{type:'FeatureCollection',features:[]}},cells:{type:'geojson',data:{type:'FeatureCollection',features:[]}}},layers:[{id:'background',type:'background',paint:{'background-color':'#c5d8c2'}},{id:'imagery',type:'raster',source:'imagery'},{id:'region',type:'fill',source:'region',paint:{'fill-color':'#c3e9c1','fill-opacity':0.12}},{id:'border',type:'line',source:'region',paint:{'line-color':'#fff','line-width':2}},{id:'cell-fill',type:'fill',source:'cells',paint:{'fill-color':['case',['==',['get','combined'],null],'#9ca3a1',['<',['get','combined'],.25],'#4c9f69',['<',['get','combined'],.75],'#efcc51',['<',['get','combined'],.9],'#ee963d','#d84442'],'fill-opacity':.75}},{id:'cell-line',type:'line',source:'cells',paint:{'line-color':'#fff','line-width':.6}},{id:'points',type:'circle',source:'detections',paint:{'circle-radius':['interpolate',['linear'],['zoom'],5,3,10,6],'circle-color':['match',['get','sensor'],'MODIS','#ffd65a','#ef453e'],'circle-stroke-color':'#fff','circle-stroke-width':1}}]}});map.addControl(new maplibregl.NavigationControl(),'top-right');map.on('load',draw);map.on('click','cell-fill',e=>{const p=e.features?.[0]?.properties;selectedCell.value=cells.value.features.find(f=>f.properties.x===Number(p?.x)&&f.properties.y===Number(p?.y))?.properties??null;selected.value=null});map.on('click','points',e=>{const id=Number(e.features?.[0]?.properties?.id);selected.value=data.value.find(d=>d.id===id)??null});map.on('mouseenter','points',()=>{if(map)map.getCanvas().style.cursor='pointer'});map.on('mouseleave','points',()=>{if(map)map.getCanvas().style.cursor=''})}catch(e){error.value=e instanceof Error?e.message:'No se pudo iniciar el mapa.'}})
onUnmounted(()=>{requestId++;map?.remove()})
</script>
<template><div class="map-panel">
<div class="map-toolbar huanuco-toolbar"><label><CalendarDays :size="17"/>Fecha de referencia <input v-model="selectedDate" type="date" :min="year+'-01-01'" :max="year+'-12-31'"/></label><label v-if="mode==='sensor'">Periodo<select v-model="period"><option value="today">Día</option><option value="week">Últimos 7 días</option><option value="month">Mes hasta la fecha</option></select></label><span class="toolbar-source"><MapPin :size="16"/>Huánuco · {{ mode==='sensor' ? range.start : weekStart }} a {{ mode==='sensor' ? range.end : weekEnd }} UTC</span></div>
<div class="map-workspace" :class="{'with-detail':selected || selectedCell}"><section class="map-stage" aria-label="Mapa de Huánuco"><div ref="mapElement" class="map-canvas" aria-label="Mapa de detecciones de Huánuco"/><div class="map-top-left"><div class="scope-summary"><div class="summary-title"><span class="status-dot"/>HUÁNUCO <span>· {{ year }}</span></div><dl><div><dt>{{ mode==='sensor'?'Detecciones mostradas':'Celdas con detección' }}</dt><dd>{{ busy?'…':error?'—':(mode==='sensor'?data.length:cells.features.length).toLocaleString('es-PE') }}</dd></div><div><dt>Área seleccionada</dt><dd>Departamento</dd></div></dl><p>{{ busy?'Consultando…':mode==='sensor'?'Centros de píxeles · UTC':'Semana ISO · índice experimental' }}</p><p v-if="mode==='sensor' && truncated">Se muestran los 20.000 puntos más recientes.</p></div></div><div class="map-bottom-left"><div class="map-legend"><template v-if="mode==='sensor'"><h4>Sensor</h4><div><span><i style="background:#ffd65a"/>MODIS</span><span><i style="background:#ef453e"/>VIIRS Suomi</span></div><small>Selecciona un punto para ver sus datos.</small></template><template v-else><h4>Índice experimental</h4><div><span><i style="background:#4c9f69"/>&lt;25%</span><span><i style="background:#efcc51"/>25–74%</span><span><i style="background:#ee963d"/>75–89%</span><span><i style="background:#d84442"/>≥90%</span><span><i style="background:#9ca3a1"/>Sin comparación</span></div><small>Solo celdas con detecciones. Selecciona una celda para ver su referencia.</small></template></div></div><div v-if="error" class="tile-notice" role="alert">{{ error }}</div></section>
<aside v-if="selected" class="detail-panel observation-detail"><button class="icon-button" aria-label="Cerrar detalle" @click="selected=null"><X :size="19"/></button><span class="eyebrow">OBSERVACIÓN SATELITAL</span><h2>Huánuco</h2><p>{{ selected.sensor }} · {{ selected.satellite }}</p><dl class="data-list"><div><dt>Fecha UTC</dt><dd>{{ selected.acquired_at }}</dd></div><div><dt>Coordenadas</dt><dd>{{ selected.latitude.toFixed(4) }}, {{ selected.longitude.toFixed(4) }}</dd></div><div><dt>FRP</dt><dd>{{ selected.frp === null ? 'Sin dato' : selected.frp.toFixed(1)+' MW' }}</dd></div><div><dt>Confianza original</dt><dd>{{ selected.confidence }}</dd></div><div><dt>Producto</dt><dd>{{ selected.version }} · {{ selected.source_kind }}</dd></div></dl><p class="inline-note">Una observación no es un incendio único ni confirma su causa.</p></aside><aside v-if="selectedCell" class="detail-panel observation-detail"><button class="icon-button" aria-label="Cerrar detalle" @click="selectedCell=null"><X :size="19"/></button><span class="eyebrow">CELDA · SEMANA ISO</span><h2>Índice {{ percent(selectedCell.combined) }}</h2><p>Cuadrícula {{ grid }} km · {{ weekStart }} a {{ weekEnd }}</p><p v-if="selectedCell.combined===null">Sin comparación: periodo incompleto o referencia con demasiados empates.</p><p v-else-if="selectedCell.disagreement!==null && selectedCell.disagreement>.25">Sensores discrepan en {{ percent(selectedCell.disagreement) }}.</p><details><summary>Ver componentes por sensor</summary><p v-for="sensor in ['MODIS','VIIRS']" :key="sensor">{{ sensor }}: {{ selectedCell.sensors[sensor].days ?? '—' }} días con detección · percentil {{ percent(selectedCell.sensors[sensor].percentile) }} · {{ selectedCell.sensors[sensor].sample }} semanas de referencia</p></details><p class="inline-note">Cero registros no prueba observación útil ni ausencia de fuego.</p></aside></div><p class="fine-print">Sin puntos no confirma ausencia de fuego. El último dato disponible de VIIRS es {{ analysis?.ends.VIIRS ?? 'desconocido' }}; MODIS: {{ analysis?.ends.MODIS ?? 'desconocido' }}.</p></div></template>
